import { WebClient } from "@slack/web-api";

export const slack = new WebClient(process.env.SLACK_BOT_TOKEN);

export async function postMessage(
  channel: string,
  text: string,
  blocks?: object[],
): Promise<void> {
  await slack.chat.postMessage({ channel, text, blocks });
}

export async function sendWebhook(text: string): Promise<void> {
  const url = process.env.SLACK_WEBHOOK_URL;
  if (!url) throw new Error("SLACK_WEBHOOK_URL not set");
  await fetch(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ text }),
  });
}

export async function postAlert(opts: {
  channel: string;
  title: string;
  message: string;
  severity?: "info" | "warning" | "error";
}): Promise<void> {
  const color = opts.severity === "error" ? "#e53e3e" : opts.severity === "warning" ? "#dd6b20" : "#3182ce";
  await slack.chat.postMessage({
    channel: opts.channel,
    text: opts.title,
    attachments: [{ color, text: opts.message }],
  });
}
